  "risk": {
    "level": "medium",
    "touches": [
      "rpc_api",
      "other"
    ],
    "why": "Flaws in index key encoding, LevelDB range seeks, or RPC byte-budget enforcement could cause incorrect transaction history results, LevelDB corruption, or excessive disk I/O DoS on the node."
  }
